const FILE_TYPES={
  video:["mp4","webm","avi","mpg","mpeg","mkv","rm","rmvb","mov","wmv","asf","ts","flv","3gp","m4v"],
  audio:["mp3","flac","wav","ogg","m4a","aac","wma","alac"],
  image:["bmp","jpg","jpeg","png","gif","svg","tiff","ico"],
  code:["php","css","go","java","js","json","txt","sh","html","xml","py","rb","c","cpp","h","hpp"],
  archive:["zip","rar","tar","7z","gz"],
  document:["pdf","doc","docx","xls","xlsx","ppt","pptx"],
  markdown:["md"]
};

const GDOC_TYPES={
  "application/vnd.google-apps.document":{
    icon:'<i class="bi bi-file-earmark-text gdi-icon-doc"></i>',
    name:"Google Doc",
    formats:[{label:"PDF",ext:"pdf"},{label:"DOCX",ext:"docx"},{label:"TXT",ext:"txt"}]
  },
  "application/vnd.google-apps.spreadsheet":{
    icon:'<i class="bi bi-file-earmark-spreadsheet gdi-icon-doc"></i>',
    name:"Google Sheet",
    formats:[{label:"PDF",ext:"pdf"},{label:"XLSX",ext:"xlsx"},{label:"CSV",ext:"csv"}]
  },
  "application/vnd.google-apps.presentation":{
    icon:'<i class="bi bi-file-earmark-slides gdi-icon-doc"></i>',
    name:"Google Slides",
    formats:[{label:"PDF",ext:"pdf"},{label:"PPTX",ext:"pptx"}]
  }
};

function isFileType(ext, type){
  return FILE_TYPES[type] && FILE_TYPES[type].includes(ext?.toLowerCase());
}

function getFileIcon(ext){
  const e = ext?.toLowerCase();
  return isFileType(e, "video") ? '<i class="bi bi-camera-video-fill gdi-icon-video"></i>' :
    isFileType(e, "audio") ? '<i class="bi bi-music-note-beamed gdi-icon-audio"></i>' :
    isFileType(e, "image") ? '<i class="bi bi-image gdi-icon-image"></i>' :
    isFileType(e, "archive") ? '<i class="bi bi-file-earmark-zip-fill gdi-icon-archive"></i>' :
    isFileType(e, "markdown") ? '<i class="bi bi-markdown-fill gdi-icon-md"></i>' :
    e === "pdf" ? '<i class="bi bi-file-earmark-pdf-fill gdi-icon-pdf"></i>' :
    isFileType(e, "code") ? '<i class="bi bi-code-slash gdi-icon-code"></i>' :
    '<i class="bi bi-file-earmark gdi-icon-file"></i>';
}

function generateBreadcrumb(path){
  const parts = path.split("/").filter(p => p);
  let html = "";
  let currentPath = "";
  
  for(let i = 0; i < parts.length; i++){
    let part = parts[i];
    currentPath += (i === 0 ? "" : "/") + part;
    
    const isLast = i === parts.length - 1;
    let displayName;
    
    try {
      displayName = decodeURIComponent(part);
    } catch {
      displayName = part;
    }
    
    const driveMatch = displayName.match(/^(\d+):$/);
    if (driveMatch) {
      displayName = (window.drive_names && window.drive_names[+driveMatch[1]]) || displayName;
    }
    
    if (!displayName) displayName = "Home";
    
    const shortName = displayName.length > 20 ? displayName.slice(0, 16) + "…" : displayName;
    
    if (isLast) {
      html += `<li class="gdi-bc-cur" title="${escHtml(displayName)}">${escHtml(shortName)}</li>`;
    } else {
      html += `<li><a href="/${currentPath}/" title="${escHtml(displayName)}">${escHtml(shortName)}</a></li><li class="gdi-bc-sep">/</li>`;
    }
  }
  
  return html;
}

const Os = {
  isWindows: navigator.userAgent.toUpperCase().indexOf("WIN") > -1,
  isMac: navigator.userAgent.toUpperCase().indexOf("MAC") > -1,
  isMacLike: /(Mac|iPhone|iPod|iPad)/i.test(navigator.userAgent),
  isIos: /(iPhone|iPod|iPad)/i.test(navigator.userAgent),
  isMobile: /Android|webOS|iPhone|iPad|iPod|iOS|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)
};

function getDocumentHeight(){
  const d = document;
  return Math.max(
    d.body.scrollHeight, d.documentElement.scrollHeight,
    d.body.offsetHeight, d.documentElement.offsetHeight,
    d.body.clientHeight, d.documentElement.clientHeight
  );
}

function getQueryVariable(variable){
  const query = window.location.search.substring(1);
  const vars = query.split("&");
  for(let i = 0; i < vars.length; i++){
    const pair = vars[i].split("=");
    if(pair[0] == variable) return pair.slice(1).join("=");
  }
  return false;
}

function escHtml(str){
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;");
}

function trimChar(str, char){
  if(char) return str.replace(new RegExp("^\\" + char + "+|\\" + char + "+$", "g"), "");
  return str.trim();
}

function applyTheme(theme){
  document.documentElement.setAttribute("data-bs-theme", theme);
  const icon = document.getElementById("theme-icon");
  if(icon) icon.className = theme === "dark" ? "bi bi-moon-stars" : "bi bi-sun";
}

function toggleTheme(){
  const current = (document.documentElement.getAttribute("data-bs-theme") || "dark") === "dark" ? "light" : "dark";
  localStorage.setItem("gdi-theme", current);
  applyTheme(current);
}

(function(){
  const theme = localStorage.getItem("gdi-theme") || "dark";
  applyTheme(theme);
})();

function sleep(ms){
  return new Promise(resolve => setTimeout(resolve, ms));
}

