// SISTEMA DE USUÁRIO - PERSISTÊNCIA
// ════════════════════════════════════════════════════════════════════

const GDIUserSystem = {
  getCurrentUser(){
    return getCookie("root_id") || "anonymous";
  },
  
  loadUserData(){
    try {
      const user = this.getCurrentUser();
      const key = `gdi_user_${user}`;
      const data = localStorage.getItem(key);
      
      if(data){
        const parsed = JSON.parse(data);
        window.GDI_USER_DATA = {
          notes: parsed.notes || {},
          progress: parsed.progress || {},
          prefs: parsed.prefs || {},
          user: user
        };
        console.log("[GDI] User loaded:", { user, notes: Object.keys(parsed.notes || {}).length });
        return parsed;
      } else {
        window.GDI_USER_DATA = { notes: {}, progress: {}, prefs: {}, user: user };
        console.log("[GDI] New user:", user);
      }
    } catch(err) {
      console.error("[GDI] Load error:", err);
      window.GDI_USER_DATA = { notes: {}, progress: {}, prefs: {}, user: "anonymous" };
    }
  },
  
  saveUserData(){
    try {
      const user = window.GDI_USER_DATA?.user || this.getCurrentUser();
      const key = `gdi_user_${user}`;
      const data = {
        user: user,
        notes: window.GDI_USER_DATA?.notes || {},
        progress: window.GDI_USER_DATA?.progress || {},
        prefs: window.GDI_USER_DATA?.prefs || {},
        timestamp: new Date().toISOString()
      };
      localStorage.setItem(key, JSON.stringify(data));
    } catch(err) {
      console.error("[GDI] Save error:", err);
    }
  },
  
  addNote(path, text){
    if(!window.GDI_USER_DATA) this.loadUserData();
    if(!window.GDI_USER_DATA.notes[path]) window.GDI_USER_DATA.notes[path] = [];
    
    const time = window._gdiPlayerInstance?.currentTime?.() ?? window._gdiPlayerInstance?.currentTime ?? 0;
    
    window.GDI_USER_DATA.notes[path].push({
      text,
      timestamp: new Date().toISOString(),
      position: Math.floor(time)
    });
    
    this.saveUserData();
    showToast("✏️ Anotação salva!");
  },
  
  getNotes(path){
    if(!window.GDI_USER_DATA) this.loadUserData();
    return window.GDI_USER_DATA.notes[path] || [];
  },
  
  removeNote(path, idx){
    if(!window.GDI_USER_DATA) this.loadUserData();
    if(window.GDI_USER_DATA.notes[path]){
      window.GDI_USER_DATA.notes[path].splice(idx, 1);
      this.saveUserData();
      showToast("🗑️ Anotação removida!");
    }
  },
  
  saveProgress(path, currentTime, duration){
    if(!window.GDI_USER_DATA) this.loadUserData();
    window.GDI_USER_DATA.progress[path] = {
      currentTime,
      duration,
      percentage: Math.floor(currentTime / duration * 100),
      lastWatched: new Date().toISOString()
    };
    this.saveUserData();
  },
  
  getProgress(path){
    if(!window.GDI_USER_DATA) this.loadUserData();
    return window.GDI_USER_DATA.progress[path] || null;
  },
  
  getLastWatchedFile(){
    if(!window.GDI_USER_DATA) this.loadUserData();
    let lastFile = null;
    let lastTime = null;
    
    for(const [file, prog] of Object.entries(window.GDI_USER_DATA.progress || {})){
      if(prog?.lastWatched){
        const t = new Date(prog.lastWatched);
        if(!lastTime || t > lastTime){
          lastTime = t;
          lastFile = file;
        }
      }
    }
    
    return lastFile ? { file: lastFile, progress: window.GDI_USER_DATA.progress[lastFile] } : null;
  }
};

// ════════════════════════════════════════════════════════════════════
// POMODORO SYSTEM (mantido igual)
// ════════════════════════════════════════════════════════════════════

const GDIPomodoroSystem = (() => {
  if(window.__gdiPomodoroBooted) return window.__gdiPomodoroInstance;
  window.__gdiPomodoroBooted = true;
  
  const CSS = `
#gdi-pom-root{position:fixed;bottom:76px;right:16px;z-index:10000;font-family:inherit;}
#gdi-pom-fab{width:48px;height:48px;border-radius:50%;background:rgba(240,136,62,0.92);border:2px solid rgba(255,255,255,0.2);box-shadow:0 4px 20px rgba(240,136,62,0.4);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:24px;transition:transform 0.2s,box-shadow 0.2s;user-select:none;position:relative;}
#gdi-pom-fab:hover{transform:scale(1.12);box-shadow:0 6px 28px rgba(240,136,62,0.6);}
#gdi-pom-fab-time{position:absolute;bottom:-16px;font-size:9px;font-weight:700;color:#f0f6fc;white-space:nowrap;letter-spacing:.05em;background:rgba(18,18,28,0.9);padding:2px 6px;border-radius:6px;}
#gdi-pom-panel{position:absolute;bottom:60px;right:0;width:240px;background:rgba(14,14,22,0.97);border:1.5px solid rgba(255,255,255,0.13);border-radius:14px;box-shadow:0 10px 40px rgba(0,0,0,0.6);padding:14px 16px;display:none;z-index:10001;}
#gdi-pom-panel.open{display:block;}
.gdi-pom-phase-label{font-size:11px;font-weight:700;letter-spacing:.08em;margin-bottom:6px;text-align:center;text-transform:uppercase;}
#gdi-pom-display{font-size:40px;font-weight:800;text-align:center;color:#f0f6fc;letter-spacing:.04em;font-variant-numeric:tabular-nums;line-height:1.1;margin-bottom:8px;}
#gdi-pom-progress{height:4px;background:rgba(255,255,255,0.1);border-radius:2px;margin:8px 0;overflow:hidden;}
#gdi-pom-progress-bar{height:4px;background:#f0883e;border-radius:2px;width:100%;transition:width 0.5s linear;}
.gdi-pom-btns{display:flex;gap:6px;margin-bottom:10px;}
.gdi-pom-btn{flex:1;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.13);color:#e6edf3;border-radius:6px;padding:5px;cursor:pointer;font-size:11px;font-weight:600;transition:all 0.15s;}
.gdi-pom-btn:hover{background:rgba(255,255,255,0.15);}
.gdi-pom-btn:disabled{opacity:0.4;cursor:not-allowed;}
#gdi-pom-divider{height:1px;background:rgba(255,255,255,0.08);margin:8px 0;}
#gdi-pom-cfg{display:flex;flex-direction:column;gap:5px;font-size:11px;color:#8b949e;}
.gdi-pom-cfg-row{display:flex;justify-content:space-between;align-items:center;}
.gdi-pom-cfg-row input{width:45px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.13);border-radius:5px;color:#f0f6fc;text-align:center;padding:3px;font-size:11px;}
@keyframes gdi-pom-pulse{0%,100%{box-shadow:0 4px 20px rgba(240,136,62,0.4);}50%{box-shadow:0 0 0 12px rgba(255,100,100,0.2),0 4px 20px rgba(240,136,62,0.4);}}
#gdi-pom-fab.warning{animation:gdi-pom-pulse 0.8s ease-in-out infinite;}
`;
  
  const styleEl = document.createElement('style');
  styleEl.textContent = CSS;
  document.head.appendChild(styleEl);
  
  const root = document.createElement('div');
  root.id = 'gdi-pom-root';
  root.innerHTML = `
<div id="gdi-pom-fab" title="🍅 Pomodoro">
  🍅
  <span id="gdi-pom-fab-time">25:00</span>
</div>
<div id="gdi-pom-panel">
  <div class="gdi-pom-phase-label" id="gdi-pom-phase">🍅 FOCO</div>
  <div id="gdi-pom-display">25:00</div>
  <div id="gdi-pom-progress"><div id="gdi-pom-progress-bar"></div></div>
  <div class="gdi-pom-btns">
    <button class="gdi-pom-btn" id="gdi-pom-start">▶ Iniciar</button>
    <button class="gdi-pom-btn" id="gdi-pom-skip">⏭</button>
    <button class="gdi-pom-btn" id="gdi-pom-reset">↺</button>
  </div>
  <div id="gdi-pom-divider"></div>
  <div id="gdi-pom-cfg">
    <div class="gdi-pom-cfg-row"><span>🍅 Foco</span><input id="gdi-pom-c-work" type="number" min="1" value="25"></div>
    <div class="gdi-pom-cfg-row"><span>☕ Pausa</span><input id="gdi-pom-c-short" type="number" min="1" value="5"></div>
    <div class="gdi-pom-cfg-row"><span>🛋 Longa</span><input id="gdi-pom-c-long" type="number" min="1" value="15"></div>
    <div class="gdi-pom-cfg-row"><span>🔄 Sessões</span><input id="gdi-pom-c-sess" type="number" min="1" value="4"></div>
  </div>
</div>`;
  document.body.appendChild(root);
  
  let cfg = {work: 25, short: 5, long: 15, sessions: 4};
  try {
    const s = JSON.parse(localStorage.getItem('gdi-pom-cfg') || '{}');
    if(s.work) cfg = {...cfg, ...s};
  } catch(e) {}
  
  let phase = 'work', totalSecs = cfg.work * 60, remainSecs = cfg.work * 60;
  let running = false, timer = null, completedSessions = 0;
  
  function fmt(s){ return String(Math.floor(s/60)).padStart(2,'0') + ':' + String(s%60).padStart(2,'0'); }
  
  function updateUI(){
    const timeStr = fmt(remainSecs);
    const pct = remainSecs / totalSecs * 100;
    const warn = remainSecs <= 10 && remainSecs > 0;
    
    document.getElementById('gdi-pom-display').textContent = timeStr;
    document.getElementById('gdi-pom-display').style.color = warn ? '#ff6b6b' : '#f0f6fc';
    document.getElementById('gdi-pom-fab-time').textContent = timeStr;
    
    const bar = document.getElementById('gdi-pom-progress-bar');
    bar.style.width = pct + '%';
    bar.style.background = warn ? '#ff6b6b' : '#f0883e';
    
    const phaseEl = document.getElementById('gdi-pom-phase');
    if(phase === 'work') phaseEl.innerHTML = '🍅 FOCO';
    else if(phase === 'short') phaseEl.innerHTML = '☕ PAUSA';
    else phaseEl.innerHTML = '🛋 PAUSA LONGA';
    
    document.getElementById('gdi-pom-start').textContent = running ? '⏸ Pausar' : '▶ Iniciar';
    
    const fab = document.getElementById('gdi-pom-fab');
    if(warn && running) fab.classList.add('warning');
    else fab.classList.remove('warning');
  }
  
  function startTimer(){
    clearInterval(timer);
    running = true;
    timer = setInterval(() => {
      if(remainSecs <= 0){
        if(phase === 'work'){
          completedSessions++;
          phase = completedSessions % cfg.sessions === 0 ? 'long' : 'short';
        } else {
          phase = 'work';
        }
        totalSecs = (phase === 'long' ? cfg.long : cfg.short) * 60;
        remainSecs = totalSecs;
        updateUI();
        return;
      }
      remainSecs--;
      updateUI();
    }, 1000);
    updateUI();
  }
  
  function pauseTimer(){ clearInterval(timer); running = false; updateUI(); }
  
  function resetTimer(){
    clearInterval(timer);
    running = false;
    phase = 'work';
    totalSecs = cfg.work * 60;
    remainSecs = cfg.work * 60;
    completedSessions = 0;
    updateUI();
  }
  
  document.getElementById('gdi-pom-fab').addEventListener('click', () => {
    document.getElementById('gdi-pom-panel').classList.toggle('open');
  });
  
  document.getElementById('gdi-pom-start').addEventListener('click', () => {
    running ? pauseTimer() : startTimer();
  });
  
  document.getElementById('gdi-pom-skip').addEventListener('click', () => {
    if(phase === 'work'){
      completedSessions++;
      phase = completedSessions % cfg.sessions === 0 ? 'long' : 'short';
    } else {
      phase = 'work';
    }
    totalSecs = (phase === 'long' ? cfg.long : cfg.short) * 60;
    remainSecs = totalSecs;
    clearInterval(timer);
    running = false;
    updateUI();
  });
  
  document.getElementById('gdi-pom-reset').addEventListener('click', resetTimer);
  
  ['gdi-pom-c-work', 'gdi-pom-c-short', 'gdi-pom-c-long', 'gdi-pom-c-sess'].forEach(id => {
    const el = document.getElementById(id);
    const key = id.replace('gdi-pom-c-', '');
    el.value = cfg[key];
    el.addEventListener('change', () => {
      cfg = {
        work: parseInt(document.getElementById('gdi-pom-c-work').value) || 25,
        short: parseInt(document.getElementById('gdi-pom-c-short').value) || 5,
        long: parseInt(document.getElementById('gdi-pom-c-long').value) || 15,
        sessions: parseInt(document.getElementById('gdi-pom-c-sess').value) || 4
      };
      localStorage.setItem('gdi-pom-cfg', JSON.stringify(cfg));
      if(!running){
        phase = 'work';
        totalSecs = cfg.work * 60;
        remainSecs = totalSecs;
        completedSessions = 0;
        updateUI();
      }
    });
  });
  
  updateUI();
  
  const observer = new MutationObserver(() => {
    if(!document.body.contains(root)) document.body.appendChild(root);
  });
  observer.observe(document.body, {childList: true});
  
  return { start: startTimer, pause: pauseTimer, reset: resetTimer, updateUI: updateUI };
})();

window.__gdiPomodoroInstance = GDIPomodoroSystem;

