function title(path){
  try { path = decodeURI(path); } catch {}
  
  const driveIndex = window.current_drive_order || 0;
  const driveName = (window.drive_names && window.drive_names[driveIndex]) || "Drive";
  path = path.replace(`/${driveIndex}:`, "");
  
  const model = window.MODEL || {};
  if(model.is_search_page){
    $("title").html(`${driveName} - Search: ${model.q || ""}`);
  } else {
    $("title").html(`${driveName} - ${path}`);
  }
}

function nav(path){
  const model = window.MODEL || {};
  const driveIndex = window.current_drive_order || 0;
  const driveName = (window.drive_names && window.drive_names[driveIndex]) || "Drive";
    const driveNames = window.drive_names || [];
  const UI = window.UI || {};
  const searchQuery = model.is_search_page && model.q || "";
  
  // Build drive dropdown
  let driveDropdown = "";
  driveNames.forEach((name, index) => {
    driveDropdown += `<li><a class="dropdown-item${index === driveIndex ? " active" : ""}" href="/${index}:/">
      <i class="bi bi-folder2-open"></i> ${name}</a></li>`;
  });
  
  // Build logo
  const logo = UI.logo_image ? 
    `<img src="${UI.logo_link_name}" alt="${UI.company_name}" height="28">` : 
    `<i class="bi bi-cloud-fill"></i> ${UI.logo_link_name}`;
  
  // Build search bar (only for non-root type 2)
  const searchBar = (model.root_type === undefined || model.root_type < 2) ? `
    <div class="gdi-nav-search">
      <form class="gdi-search-form" method="get" action="/${driveIndex}:search">
        <input class="gdi-search-input" name="q" type="search" placeholder="Search files…" value="${escHtml(searchQuery)}">
        <button class="gdi-search-btn" type="submit"><i class="bi bi-search"></i></button>
      </form>
    </div>` : "";
  
  const navHtml = `
<nav class="gdi-nav">
  <div class="gdi-nav-inner">
    <a class="gdi-logo" href="/${driveIndex}:/">${logo}</a>
    <div class="gdi-nav-sep"></div>
    ${searchBar}
    <div class="gdi-nav-actions">
      <div class="dropdown">
        <button class="gdi-nav-btn dropdown-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false">
          <i class="bi bi-grid-3x3-gap-fill"></i>
          <span class="d-none d-md-inline">${escHtml(driveName)}</span>
        </button>
        <ul class="dropdown-menu dropdown-menu-end">${driveDropdown}</ul>
      </div>
      <div class="gdi-nav-sep"></div>
      <button id="theme-toggle" class="gdi-nav-btn" onclick="toggleTheme()" title="Toggle theme">
        <i class="bi bi-moon-stars" id="theme-icon"></i>
      </button>
      ${UI.show_logout_button ? '<a class="gdi-nav-btn" href="/logout" title="Logout"><i class="bi bi-box-arrow-right"></i></a>' : ""}
    </div>
  </div>
</nav>`;
  
  $("#nav").html(navHtml);
  applyTheme(localStorage.getItem("gdi-theme") || "dark");
}

// ════════════════════════════════════════════════════════════════════
// REQUISIÇÕES
// ════════════════════════════════════════════════════════════════════

function requestListPath(path, params, callback, retries = 3, isFallback = false) {
  const payload = {
    id: params.id || "",
    type: "folder",
    password: params.password || "",
    page_token: params.page_token || "",
    page_index: params.page_index || 0
  };
  
  const requestPath = isFallback ? "/0:fallback" : path;
  const abortController = new AbortController();
  const requestId = `${requestPath}_${Date.now()}_${Math.random()}`;
  
  if(!window.GDI_ABORT) window.GDI_ABORT = new Map();
  window.GDI_ABORT.set(requestId, abortController);
  
  $("#update").show();
  $("#update").html('<div class="gdi-alert gdi-alert-info">Connecting…</div>');
  
  async function attempt(remainingRetries) {
    try {
      const response = await fetch(requestPath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        signal: abortController.signal
      });
      
      if(!response.ok) throw new Error("Request failed with status " + response.status);
      
      const data = await response.json();
      
      if(data && data.error && data.error.code === 401) {
        $("#update").hide();
        askPassword(path);
        return;
      }
      
      if(data && data.data === null) {
        document.getElementById("spinner")?.remove();
        $("#list").html(`<div class="gdi-empty"><i class="bi bi-exclamation-circle"></i><p>Server didn't send any data.</p></div>`);
        $("#update").hide();
        return;
      }
      
      if(data && data.data) {
        callback(data, path, payload);
        $("#update").hide();
        window.GDI_ABORT.delete(requestId);
        return;
      }
      
      throw new Error("Invalid response format");
      
    } catch(error) {
      window.GDI_ABORT.delete(requestId);
      
      if(error.name === 'AbortError') {
        console.log('Request cancelled');
        return;
      }
      
      if(remainingRetries > 0) {
        $("#update").html(`<div class="gdi-alert gdi-alert-info">Retrying… (${remainingRetries} left)</div>`);
        await sleep(2000);
        await attempt(remainingRetries - 1);
      } else {
        $("#update").html('<div class="gdi-alert gdi-alert-error">Unable to connect. Please try again.</div>');
        $("#list").html(`<div class="gdi-empty"><i class="bi bi-wifi-off"></i><p>${escHtml(String(error))}</p></div>`);
        $("#update").hide();
      }
    }
  }
  
  attempt(retries);
}

function requestSearch(params, callback, retries = 3) {
  const payload = {
    q: params.q || null,
    page_token: params.page_token || null,
    page_index: params.page_index || 0
  };
  
  async function attempt(remainingRetries) {
    try {
      const response = await fetch(`/${window.current_drive_order || 0}:search`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      
      if(!response.ok) throw new Error("Request failed with status " + response.status);
      
      const data = await response.json();
      
      if(data && data.data === null) {
        $("#spinner").remove();
        $("#list").html('<div class="gdi-empty"><i class="bi bi-search"></i><p>No results found.</p></div>');
        $("#update").remove();
        return;
      }
      
      if(data && data.data) {
        callback && callback(data, payload);
        $("#update").remove();
        return;
      }
      
      throw new Error("Invalid response format");
      
    } catch(error) {
      if(remainingRetries > 0) {
        $("#update").html(`<div class="gdi-alert gdi-alert-info">Retrying… (${remainingRetries} left)</div>`);
        await sleep(2000);
        await attempt(remainingRetries - 1);
      } else {
        $("#update").html(`<div class="gdi-alert gdi-alert-error">Unable to connect after ${retries} attempts.</div>`);
        $("#list").html('<div class="gdi-empty"><i class="bi bi-wifi-off"></i><p>Connection failed.</p></div>');
        $("#spinner").remove();
      }
    }
  }
  
  $("#update").html('<div class="gdi-alert gdi-alert-info">Searching…</div>');
  attempt(retries);
}

// ════════════════════════════════════════════════════════════════════
// RENDER - PRINCIPAL (CORRIGIDO)
// ════════════════════════════════════════════════════════════════════

function render(path) {
  console.log("[GDI] Render called with path:", path);
  
  // Remove query string if present
  if(path.indexOf("?") >= 0) {
    path = path.substr(0, path.indexOf("?"));
  }
  
  title(path);
  nav(path);
  
  // Check if it's a fallback path
  if(path.includes("/fallback")) {
    window.scroll_status = { event_bound: false, loading_lock: false };
    const action = getQueryVariable("a");
    const id = decodeURIComponent(getQueryVariable("id") || "");
    
    if(action) {
      return fallback(id, true);
    } else {
      return list(null, id, true);
    }
  }
  
  // Check if it's a search page
  if(window.MODEL?.is_search_page) {
    window.scroll_status = { event_bound: false, loading_lock: false };
    return render_search_result_list();
  }
  
  // Check if it's a folder (ends with / or matches drive pattern like /0:)
  const isDriveRoot = /\/\d+:\/?$/.test(path);
  const isFolder = path.slice(-1) === "/" || isDriveRoot;
  
  if(isFolder) {
    window.scroll_status = { event_bound: false, loading_lock: false };
    return list(path);
  }
  
  // Otherwise, treat as file
  file(path);
}

// ════════════════════════════════════════════════════════════════════
// LIST VIEW - PASTA (CORRIGIDO)
// ════════════════════════════════════════════════════════════════════

function list(path, fallbackId = "", isFallback = false) {
  console.log("[GDI] List view for:", path, "fallback:", isFallback, "id:", fallbackId);
  
  const currentPath = window.location.pathname;
  const pathParts = trimChar(currentPath, "/").split("/").filter(p => p);
  
  // Build breadcrumb
  let currentBreadcrumbPath = "/";
  let breadcrumbHtml = '<li><a href="/">Home</a></li><li class="gdi-bc-sep">/</li>';
  
  if(pathParts.length > 0) {
    for(let i = 0; i < pathParts.length; i++) {
      let part = pathParts[i];
      let displayName;
      
      try {
        displayName = decodeURIComponent(part);
      } catch {
        displayName = part;
      }
      
      displayName = displayName.replace(/\//g, "%2F");
      
      const driveMatch = displayName.match(/^(\d+):$/);
      if(driveMatch && window.drive_names && window.drive_names[+driveMatch[1]]) {
        displayName = window.drive_names[+driveMatch[1]];
      }
      
      currentBreadcrumbPath += part + "/";
      
      const shortName = displayName.length > 18 ? displayName.slice(0, 14) + "…" : displayName;
      
      if(!displayName) break;
      
      if(i === pathParts.length - 1) {
        breadcrumbHtml += `<li class="gdi-bc-cur" title="${escHtml(displayName)}">${escHtml(shortName)}</li>`;
      } else {
        breadcrumbHtml += `<li><a href="${currentBreadcrumbPath}" title="${escHtml(displayName)}">${escHtml(shortName)}</a></li><li class="gdi-bc-sep">/</li>`;
      }
    }
  }
  
  const listHtml = `
<div class="gdi-wrap">
  <div id="update"></div>
  <div id="head_md" class="gdi-panel gdi-markdown" style="display:none;"></div>
  <div id="select_items" class="gdi-select-bar" style="display:none;">
    <label style="display:flex;align-items:center;gap:6px;cursor:pointer;">
      <input type="checkbox" id="select-all-checkboxes"> Select all
    </label>
    <button id="handle-multiple-items-copy" class="gdi-btn gdi-btn-ghost">
      <i class="bi bi-clipboard"></i> Copy selected
    </button>
  </div>
  <div class="gdi-breadcrumb-wrap">
    <ol class="gdi-bc" id="folderne">${breadcrumbHtml}</ol>
  </div>
  <div class="gdi-panel">
    <div class="gdi-toolbar">
      <input id="folder-filter" class="gdi-filter-input" type="search" placeholder="Filter files…" autocomplete="off">
    </div>
    <div class="gdi-list-header" id="list-header">
      <span class="gdi-col-name gdi-sort-header" data-sort="name">Name</span>
      <span class="gdi-col-size gdi-sort-header" data-sort="size">Size</span>
      <span class="gdi-col-date gdi-sort-header" data-sort="date">Modified</span>
      <span class="gdi-col-acts"></span>
    </div>
    <div id="list"></div>
    <div id="count" class="gdi-count-bar"></div>
  </div>
  <div id="readme_md" class="gdi-panel gdi-markdown" style="display:none;"></div>
</div>`;
  
  $("#content").html(listHtml);
  
  const savedPassword = localStorage.getItem("password" + path);
  $("#list").html('<div class="gdi-spinner-wrap" id="spinner"><div class="gdi-spinner"></div></div>');
  $("#readme_md").hide().html("");
  $("#head_md").hide().html("");
  
  function handleResponse(data, requestPath, payload) {
    $("#list").data("nextPageToken", data.nextPageToken);
    $("#list").data("curPageIndex", data.curPageIndex);
    $("#spinner").remove();
    
    if(data.nextPageToken === null) {
      $(window).off("scroll");
      window.scroll_status.event_bound = false;
      window.scroll_status.loading_lock = false;
      
      if(isFallback) {
        append_files_to_fallback_list(requestPath, data.data.files);
      } else {
        append_files_to_list(requestPath, data.data.files);
      }
    } else {
      if(isFallback) {
        append_files_to_fallback_list(requestPath, data.data.files);
      } else {
        append_files_to_list(requestPath, data.data.files);
      }
      
      if(window.scroll_status.event_bound !== true) {
        $(window).on("scroll", function() {
          if($(this).scrollTop() + $(this).height() > getDocumentHeight() - (Os.isMobile ? 130 : 80)) {
            if(window.scroll_status.loading_lock === true) return;
            
            window.scroll_status.loading_lock = true;
            $('<div id="spinner" class="gdi-spinner-wrap"><div class="gdi-spinner"></div></div>').insertBefore("#readme_md");
            
            const listElement = $("#list");
            const nextPageToken = listElement.data("nextPageToken");
            const curPageIndex = listElement.data("curPageIndex");
            
            const requestParams = {
              id: fallbackId,
              password: payload.password,
              page_token: nextPageToken,
              page_index: curPageIndex + 1
            };
            
            requestListPath(requestPath, requestParams, handleResponse, null, 5, isFallback);
          }
        });
        window.scroll_status.event_bound = true;
      }
      
      if(window.scroll_status.loading_lock === true) {
        window.scroll_status.loading_lock = false;
      }
    }
  }
  
  const requestParams = {
    id: fallbackId,
    password: savedPassword
  };
  
  requestListPath(path, requestParams, handleResponse, null, 3, isFallback);
  
  // Handle copy selected items
  const copyButton = document.getElementById("handle-multiple-items-copy");
  if(copyButton) {
    copyButton.addEventListener("click", () => {
      const checkedItems = document.querySelectorAll("input.gdi-row-check:checked");
      if(!checkedItems.length) {
        alert("No items selected!");
        return;
      }
      
      const links = Array.from(checkedItems).map(item => item.value).join("\n");
      
      navigator.clipboard.writeText(links).catch(() => {
        const textarea = document.createElement("textarea");
        textarea.value = links;
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand("copy");
        document.body.removeChild(textarea);
      });
      
      showToast(`${checkedItems.length} link${checkedItems.length > 1 ? "s" : ""} copied`);
    });
  }
}

function append_files_to_list(basePath, files) {
  const UI = window.UI || {};
  const listElement = $("#list");
  const isLastPage = listElement.data("nextPageToken") === null;
  const isFirstPage = listElement.data("curPageIndex") == "0";
  
  let html = "";
  let totalSize = 0;
  let hasFiles = false;
  
  for(const index in files) {
    const file = files[index];
    const encodedName = encodeURIComponent(file.name).replace(/\//g, "%2F") + "/";
    const filePath = basePath + encodedName.replace(/#/g, "%23").replace(/\?/g, "%3F");
    
    if(file.modifiedTime) {
      file.modifiedTime = utc2delhi(file.modifiedTime);
    }
    
    if(file.mimeType == "application/vnd.google-apps.folder") {
      html += `<a href="${filePath}" class="gdi-row countitems" data-name="${escHtml(file.name.toLowerCase())}" data-date="${file.modifiedTime || ""}">
  <span class="gdi-row-icon"><i class="bi bi-folder-fill gdi-icon-folder"></i></span>
  <span class="gdi-row-name">${escHtml(file.name)}</span>
  <span class="gdi-row-size"></span>
  <span class="gdi-row-date">${UI.display_time ? file.modifiedTime : ""}</span>
  <span class="gdi-row-acts"></span>
</a>`;
    } else {
      const fileSize = Number(file.size);
      totalSize += fileSize;
      file.size = formatFileSize(file.size);
      hasFiles = true;
      
      const fileExt = file.fileExtension;
      const downloadUrl = UI.second_domain_for_dl ? UI.downloaddomain + file.link : window.location.origin + file.link;
      const encodedFileName = encodeURIComponent(file.name);
      const viewUrl = basePath + encodedFileName + "?a=view";
      const filePathNoView = basePath + encodedFileName;
      
      // Check for README and HEAD files
      if(isLastPage && file.name == "README.md" && UI.render_readme_md) {
        get_file(filePathNoView, file, function(content) {
          markdown("#readme_md", content);
          $("img").addClass("img-fluid");
        });
      }
      
      if(file.name == "HEAD.md" && UI.render_head_md) {
        get_file(filePathNoView, file, function(content) {
          markdown("#head_md", content);
          $("img").addClass("img-fluid");
        });
      }
      
      const gdocType = GDOC_TYPES[file.mimeType];
      const fileIcon = gdocType ? gdocType.icon : getFileIcon(fileExt);
      
      const gdocExportLinks = gdocType && UI.display_download ? 
        gdocType.formats.map(format => 
          `<a class="gdi-act-btn" href="${downloadUrl}&fmt=${format.ext}" title="Export as ${format.label}" download><span style="font-size:10px;font-weight:600;">${format.label}</span></a>`
        ).join("") : "";
      
      html += `<div class="gdi-row countitems size_items" data-name="${escHtml(file.name.toLowerCase())}" data-bytes="${fileSize}" data-date="${file.modifiedTime || ""}">
  ${UI.allow_selecting_files ? `<input class="gdi-row-check" type="checkbox" value="${downloadUrl}">` : ""}
  <span class="gdi-row-icon">${fileIcon}</span>
  <a class="gdi-row-name" href="${viewUrl}" title="${escHtml(file.name)}" data-size="${UI.display_size ? file.size : ""}">${escHtml(file.name)}</a>
  <span class="gdi-row-size">${UI.display_size ? file.size : ""}</span>
  <span class="gdi-row-date">${UI.display_time ? file.modifiedTime : ""}</span>
  <span class="gdi-row-acts">
    ${UI.allow_selecting_files ? `<button class="gdi-act-btn" onclick="copyShareUrl(this.closest('.gdi-row').querySelector('.gdi-row-name').href)" title="Copy link"><i class="bi bi-link-45deg"></i></button>` : ""}
    ${gdocType ? gdocExportLinks : (UI.display_download ? `<a class="gdi-act-btn" href="${downloadUrl}" title="Download"><i class="bi bi-download"></i></a>` : "")}
  </span>
</div>`;
    }
  }
  
  if(hasFiles && UI.allow_selecting_files) {
    document.getElementById("select_items").style.display = "flex";
  }
  
  listElement.html((isFirstPage ? "" : listElement.html()) + html);
  
  initFolderFilter();
  initColumnSort();
  
  if(isLastPage) {
    const formattedSize = formatFileSize(totalSize) || "0 Bytes";
    const totalItems = listElement.find(".countitems").length;
    const totalFiles = listElement.find(".size_items").length;
    
    const itemsText = totalItems === 0 ? "Empty folder" : `${totalItems} item${totalItems === 1 ? "" : "s"}`;
    const filesText = totalFiles > 0 ? ` · ${totalFiles} file${totalFiles === 1 ? "" : "s"}, ${formattedSize}` : "";
    
    $("#count").addClass("show").html(itemsText + filesText);
  }
}

function append_files_to_fallback_list(basePath, files) {
  const UI = window.UI || {};
  
  try {
    const listElement = $("#list");
    const isLastPage = listElement.data("nextPageToken") === null;
    const isFirstPage = listElement.data("curPageIndex") == "0";
    
    let html = "";
    let totalSize = 0;
    let hasFiles = false;
    
    for(const index in files) {
      const file = files[index];
      const fallbackUrl = "/fallback?id=" + encodeURIComponent(file.id);
      
      if(file.modifiedTime) {
        file.modifiedTime = utc2delhi(file.modifiedTime);
      }
      
      if(file.mimeType == "application/vnd.google-apps.folder") {
        html += `<a href="${fallbackUrl}" class="gdi-row countitems" data-name="${escHtml(file.name.toLowerCase())}" data-date="${file.modifiedTime || ""}">
  <span class="gdi-row-icon"><i class="bi bi-folder-fill gdi-icon-folder"></i></span>
  <span class="gdi-row-name">${escHtml(file.name)}</span>
  <span class="gdi-row-size"></span>
  <span class="gdi-row-date">${UI.display_time ? file.modifiedTime : ""}</span>
  <span class="gdi-row-acts"></span>
</a>`;
      } else {
        const fileSize = Number(file.size);
        totalSize += fileSize;
        file.size = formatFileSize(file.size);
        hasFiles = true;
        
        const fileExt = file.fileExtension;
        const downloadUrl = UI.second_domain_for_dl ? UI.downloaddomain + file.link : window.location.origin + file.link;
        const viewUrl = fallbackUrl + "&a=view";
        
        html += `<div class="gdi-row countitems size_items" data-name="${escHtml(file.name.toLowerCase())}" data-bytes="${fileSize}" data-date="${file.modifiedTime || ""}">
  ${UI.allow_selecting_files ? `<input class="gdi-row-check" type="checkbox" value="${downloadUrl}">` : ""}
  <span class="gdi-row-icon">${getFileIcon(fileExt)}</span>
  <a class="gdi-row-name" href="${viewUrl}" title="${escHtml(file.name)}" data-size="${UI.display_size ? file.size : ""}">${escHtml(file.name)}</a>
  <span class="gdi-row-size">${UI.display_size ? file.size : ""}</span>
  <span class="gdi-row-date">${UI.display_time ? file.modifiedTime : ""}</span>
  <span class="gdi-row-acts">
    ${UI.display_download ? `<a class="gdi-act-btn" href="${downloadUrl}" title="Download"><i class="bi bi-download"></i></a>` : ""}
  </span>
</div>`;
      }
    }
    
    if(hasFiles && UI.allow_selecting_files) {
      document.getElementById("select_items").style.display = "flex";
    }
    
    listElement.html((isFirstPage ? "" : listElement.html()) + html);
    
    initFolderFilter();
    initColumnSort();
    
    if(isLastPage) {
      const formattedSize = formatFileSize(totalSize) || "0 Bytes";
      const totalItems = listElement.find(".countitems").length;
      const totalFiles = listElement.find(".size_items").length;
      
      const itemsText = totalItems === 0 ? "Empty folder" : `${totalItems} item${totalItems === 1 ? "" : "s"}`;
      const filesText = totalFiles > 0 ? ` · ${totalFiles} file${totalFiles === 1 ? "" : "s"}, ${formattedSize}` : "";
      
      $("#count").addClass("show").html(itemsText + filesText);
    }
  } catch(error) {
    console.error("Error in append_files_to_fallback_list:", error);
  }
}

let _folderFilterBound = false;

function initFolderFilter() {
  const filterInput = document.getElementById("folder-filter");
  if(!filterInput || _folderFilterBound) return;
  
  _folderFilterBound = true;
  
  filterInput.addEventListener("input", function() {
    const searchTerm = this.value.toLowerCase();
    
    document.querySelectorAll("#list .gdi-row").forEach(row => {
      const rowName = (row.dataset.name || row.textContent).toLowerCase();
      row.style.display = !searchTerm || rowName.includes(searchTerm) ? "" : "none";
    });
  });
}

let _sortState = { col: null, dir: 1 };

function initColumnSort() {
  const headers = document.querySelectorAll("#list-header .gdi-sort-header");
  
  headers.forEach(header => {
    header.addEventListener("click", function() {
      const column = this.dataset.sort;
      
      if(_sortState.col === column) {
        _sortState.dir *= -1;
      } else {
        _sortState.col = column;
        _sortState.dir = 1;
      }
      
      headers.forEach(h => h.classList.remove("asc", "desc"));
      this.classList.add(_sortState.dir === 1 ? "asc" : "desc");
      
      sessionStorage.setItem("gdi-sort", JSON.stringify(_sortState));
      sortFileList(column, _sortState.dir);
    });
  });
  
  try {
    const saved = JSON.parse(sessionStorage.getItem("gdi-sort"));
    if(saved && saved.col) {
      _sortState = saved;
      
      // Apply saved sort state
      headers.forEach(h => {
        if(h.dataset.sort === saved.col) {
          h.classList.add(saved.dir === 1 ? "asc" : "desc");
        }
      });
    }
  } catch(e) {}
}

function sortFileList(column, direction) {
  const listElement = $("#list");
  const rows = listElement.children(".gdi-row").toArray();
  
  rows.sort((a, b) => {
    if(column === "size") {
      return direction * ((parseFloat($(a).data("bytes")) || 0) - (parseFloat($(b).data("bytes")) || 0));
    }
    
    if(column === "date") {
      return direction * (new Date($(a).data("date")) - new Date($(b).data("date")));
    }
    
    const nameA = ($(a).data("name") || "").toLowerCase();
    const nameB = ($(b).data("name") || "").toLowerCase();
    return direction * nameA.localeCompare(nameB);
  });
  
  rows.forEach(row => listElement.append(row));
}

function askPassword(path) {
  $("#spinner").remove();
  
  const password = prompt("This folder is password protected. Enter the password:", "");
  if(password != null && password != "") {
    localStorage.setItem("password" + path, password);
    list(path);
  } else {
    history.go(-1);
  }
}

// ════════════════════════════════════════════════════════════════════
// FILE VIEWER
// ════════════════════════════════════════════════════════════════════

async function file(path) {
  console.log("[GDI] File view for:", path);
  
  const rootId = getCookie("root_id") || "";
  $("#content").html('<div class="gdi-wrap"><div class="gdi-spinner-wrap" style="height:150px;" id="spinner"><div class="gdi-spinner"></div></div></div>');
  
  try {
    const response = await fetch("", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: path })
    });
    
    if(!response.ok) throw new Error("Request failed with status " + response.status);
    
    const data = await response.json();
    dispatchFileView(data, rootId);
  } catch(error) {
    $("#content").html(renderErrorCard(error));
  }
}

function dispatchFileView(fileData, rootId) {
  console.log("[GDI] Dispatch file view:", fileData.name);
  
  const UI = window.UI || {};
  const mimeType = fileData.mimeType;
  const fileExt = fileData.fileExtension;
  
  if(mimeType === "application/vnd.google-apps.folder") {
    window.location.href = window.location.pathname + "/";
    return;
  }
  
  if(!fileExt && !mimeType) return;
  
  const fileName = fileData.name;
  const encodedName = encodeURIComponent(fileName);
  const fileSize = formatFileSize(fileData.size);
  const downloadUrl = UI.second_domain_for_dl ? UI.downloaddomain + fileData.link : window.location.origin + fileData.link;
  
  if(GDOC_TYPES[mimeType]) {
    file_workspace(fileName, fileSize, mimeType, downloadUrl);
  } else if(FILE_TYPES.video.includes(fileExt) || (mimeType && mimeType.includes("video"))) {
    const poster = fileData.thumbnailLink ? fileData.thumbnailLink.replace("s220", "s0") : UI.poster;
    file_video(fileName, encodedName, fileSize, poster, downloadUrl, mimeType, fileData.id, rootId, fileData.subtitles || []);
  } else if(FILE_TYPES.audio.includes(fileExt) || (mimeType && mimeType.includes("audio"))) {
    file_audio(fileName, encodedName, fileSize, downloadUrl, fileData.id, rootId);
  } else if(FILE_TYPES.image.includes(fileExt) || (mimeType && mimeType.includes("image"))) {
    file_image(fileName, encodedName, fileSize, downloadUrl);
  } else if(fileExt === "pdf" || (mimeType && mimeType.includes("pdf"))) {
    file_pdf(fileName, encodedName, fileSize, downloadUrl, fileData.id, rootId);
  } else if(FILE_TYPES.code.includes(fileExt)) {
    file_code(fileName, encodedName, fileSize, fileData.size, downloadUrl, fileExt, fileData.id, rootId);
  } else {
    file_others(fileName, encodedName, fileSize, downloadUrl);
  }
}

function renderErrorCard(error) {
  return `<div class="gdi-wrap"><div class="gdi-viewer"><div class="gdi-viewer-card">
    <div class="gdi-file-header">
      <span class="gdi-file-header-icon"><i class="bi bi-exclamation-triangle-fill" style="color:#dc2626;"></i></span>
      <div class="gdi-file-header-info">
        <div class="gdi-file-header-name">Unable to load file</div>
        <div class="gdi-file-header-meta">${escHtml(String(error))}</div>
      </div>
    </div>
    <div class="gdi-viewer-footer">
      <a href="/" class="gdi-btn gdi-btn-primary"><i class="bi bi-house"></i> Home</a>
      <a href="javascript:history.back()" class="gdi-btn gdi-btn-ghost ms-2"><i class="bi bi-arrow-left"></i> Back</a>
    </div>
  </div></div></div>`;
}

function _viewerBreadcrumb() {
  return generateBreadcrumb(window.location.pathname);
}

function _viewerCard(icon, name, meta, body, footer = "") {
  return `<div class="gdi-wrap"><div class="gdi-viewer">
    <div class="gdi-breadcrumb-wrap"><ol class="gdi-bc">${_viewerBreadcrumb()}</ol></div>
    <div class="gdi-viewer-card">
      <div class="gdi-file-header">
        <span class="gdi-file-header-icon">${icon}</span>
        <div class="gdi-file-header-info">
          <div class="gdi-file-header-name">${escHtml(name)}</div>
          <div class="gdi-file-header-meta">${escHtml(meta)}</div>
        </div>
      </div>
      <div class="gdi-viewer-body">${body}</div>
      ${footer ? `<div class="gdi-viewer-footer">${footer}</div>` : ""}
    </div>
  </div></div>`;
}

// ════════════════════════════════════════════════════════════════════
// VIDEO PLAYER (MANTIDO)
// ════════════════════════════════════════════════════════════════════

function file_video(name, encodedName, size, poster, streamUrl, mimeType, fileId, rootId, subtitles = []) {
  const UI = window.UI || {};
  const playerConfig = window.player_config || {};
  subtitles = subtitles || [];
  
  const isHLS = /\.m3u8/i.test(streamUrl) || mimeType === "application/x-mpegURL";
  
  let playerHtml = "";
  let scriptSrc = "";
  let styleSrc = "";
  
  if(!UI.disable_player) {
    if(playerConfig.player === "plyr") {
      playerHtml = `<video id="player" playsinline controls autoplay muted data-poster="${poster}">
        <source src="${streamUrl}" type="${isHLS ? "application/x-mpegURL" : "video/mp4"}">
        ${subtitles.map(sub => `<track kind="subtitles" src="${escHtml(sub.url)}" label="${escHtml(sub.label)}" default>`).join("")}
      </video>`;
      scriptSrc = "https://cdn.plyr.io/" + playerConfig.plyr_io_version + "/plyr.polyfilled.js";
      styleSrc = "https://cdn.plyr.io/" + playerConfig.plyr_io_version + "/plyr.css";
    } else if(playerConfig.player === "videojs") {
      playerHtml = `<video id="vplayer" poster="${poster}" class="video-js vjs-default-skin vjs-big-play-centered" controls autoplay muted preload="auto" width="100%" height="100%" data-setup='{"fluid":true,"autoplay":true,"muted":true}'>
        <source src="${streamUrl}" type="${isHLS ? "application/x-mpegURL" : "video/mp4"}">
        <source src="${streamUrl}" type="video/webm">
        ${subtitles.map(sub => `<track kind="subtitles" src="${escHtml(sub.url)}" label="${escHtml(sub.label)}" default>`).join("")}
      </video>`;
      scriptSrc = "https://vjs.zencdn.net/" + playerConfig.videojs_version + "/video.js";
      styleSrc = "https://vjs.zencdn.net/" + playerConfig.videojs_version + "/video-js.css";
    } else if(playerConfig.player === "dplayer") {
      playerHtml = '<div id="player-container"></div>';
      scriptSrc = "https://cdn.jsdelivr.net/npm/dplayer/dist/DPlayer.min.js";
      styleSrc = "https://cdn.jsdelivr.net/npm/dplayer/dist/DPlayer.min.css";
    } else if(playerConfig.player === "jwplayer") {
      playerHtml = '<div id="player"></div>';
      scriptSrc = "https://content.jwplatform.com/libraries/IDzF9Zmk.js";
    }
  }
  
  const playerBody = `
    <div class="gdi-player-wrap" style="width:100%;margin:0 auto;">${playerHtml}</div>
    <div id="gdi-player-nav" style="display:none;justify-content:space-between;align-items:center;margin-top:10px;gap:8px;">
      <button id="gdi-btn-prev" class="gdi-btn gdi-btn-ghost" style="flex:1;" title="Aula anterior"><i class="bi bi-skip-start-fill"></i> Anterior</button>
      <span id="gdi-nav-info" style="font-size:12px;color:var(--gdi-text-muted,#aaa);white-space:nowrap;"></span>
      <button id="gdi-btn-next" class="gdi-btn gdi-btn-ghost" style="flex:1;justify-content:flex-end;" title="Próxima aula">Próxima <i class="bi bi-skip-end-fill"></i></button>
    </div>
    <div id="gdi-player-controls" style="display:flex;gap:8px;margin-top:10px;">
      <button id="gdi-toggle-notes" class="gdi-btn gdi-btn-ghost" style="flex:1;"><i class="bi bi-pencil-square"></i> Anotações</button>
    </div>
    <div id="gdi-playlist-wrap" style="margin-top:16px;display:none;">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
        <strong style="font-size:14px;"><i class="bi bi-collection-play me-2"></i>Playlist</strong>
        <span id="gdi-playlist-count" style="font-size:12px;color:var(--gdi-text-muted,#aaa);"></span>
      </div>
      <div id="gdi-playlist-list" style="max-height:260px;overflow-y:auto;border:1px solid rgba(255,255,255,0.12);border-radius:8px;padding:6px;background:rgba(0,0,0,0.2);"></div>
    </div>`;
  
  const footer = UI.disable_video_download ? "" : renderDownloadButtons(streamUrl, encodedName, { showMedia: true });
  
  $("#content").html(_viewerCard('<i class="bi bi-camera-video-fill gdi-icon-video"></i>', name, size, playerBody, footer));
  $(".gdi-viewer").css({ "max-width": "1200px", "width": "96%", "margin": "0 auto" });
  
  if(styleSrc) {
    const linkEl = document.createElement("link");
    linkEl.rel = "stylesheet";
    linkEl.href = styleSrc;
    document.head.appendChild(linkEl);
  }
  
  window._gdiPlayerInstance = null;
  
  function initPlayerEvents() {
    if(playerConfig.player === "plyr") {
      const player = new Plyr("#player", { autoplay: true, keyboard: { focused: true, global: true } });
      window._gdiPlayerInstance = player;
      
      player.on("ready", () => {
        player.play().catch(() => {});
        setTimeout(() => { player.muted = false; }, 2000);
      });
      
      player.on("ended", playNextInPlaylist);
      player.on("pause", () => {
        GDIUserSystem.saveProgress(window.location.pathname, player.currentTime, player.duration);
      });
      
      setInterval(() => {
        if(player && player.duration) {
          GDIUserSystem.saveProgress(window.location.pathname, player.currentTime, player.duration);
        }
      }, 5000);
    } else if(playerConfig.player === "videojs") {
      const player = videojs("vplayer", {
        autoplay: true,
        playbackRates: [0.5, 0.75, 1, 1.25, 1.5, 2],
        controlBar: { pictureInPictureToggle: true }
      });
      window._gdiPlayerInstance = player;
      
      player.ready(function() {
        this.play().catch(() => {});
        setTimeout(() => { this.muted(false); }, 2000);
        
        this.on("ended", () => { playNextInPlaylist(); });
        this.on("pause", () => {
          GDIUserSystem.saveProgress(window.location.pathname, this.currentTime(), this.duration());
        });
        
        setInterval(() => {
          if(this && this.duration()) {
            GDIUserSystem.saveProgress(window.location.pathname, this.currentTime(), this.duration());
          }
        }, 5000);
      });
    } else if(playerConfig.player === "dplayer") {
      const player = new DPlayer({
        container: document.getElementById("player-container"),
        autoplay: true,
        muted: true,
        screenshot: true,
        video: { url: streamUrl, pic: poster, type: isHLS ? "hls" : "auto" },
        subtitle: subtitles.length ? { url: subtitles[0].url, type: "webvtt" } : undefined
      });
      window._gdiPlayerInstance = player;
      
      player.play();
      setTimeout(() => { player.volume = 0.5; }, 2000);
      player.on("ended", playNextInPlaylist);
      
      setInterval(() => {
        if(player && player.video) {
          GDIUserSystem.saveProgress(window.location.pathname, player.video.currentTime, player.video.duration);
        }
      }, 5000);
    } else if(playerConfig.player === "jwplayer") {
      const player = jwplayer("player").setup({
        file: streamUrl,
        type: mimeType,
        autostart: true,
        mute: true,
        image: poster,
        width: "100%",
        aspectratio: "16:9",
        title: name,
        description: "Powered by Google Drive Index",
        tracks: subtitles.map(sub => ({ file: sub.url, kind: "captions", label: sub.label, default: true })),
        captions: { color: "#f3f378", fontSize: 14, backgroundOpacity: 50, edgeStyle: "raised" }
      });
      window._gdiPlayerInstance = player;
      
      setTimeout(() => { player.setMute(false); }, 2000);
      player.on("complete", playNextInPlaylist);
      
      setInterval(() => {
        const position = player.getPosition();
        const duration = player.getDuration();
        if(position >= 0 && duration > 0) {
          GDIUserSystem.saveProgress(window.location.pathname, position, duration);
        }
      }, 5000);
    }
  }
  
  if(scriptSrc) {
    if(window.Plyr || window.videojs || window.DPlayer || window.jwplayer) {
      initPlayerEvents();
    } else {
      const scriptEl = document.createElement("script");
      scriptEl.src = scriptSrc;
      scriptEl.onload = () => { initPlayerEvents(); };
      document.head.appendChild(scriptEl);
    }
  }
  
  initNotesUI();
  
  document.getElementById("gdi-toggle-notes")?.addEventListener("click", () => {
    const notesPanel = document.getElementById("gdi-notes-panel");
    if(notesPanel) {
      notesPanel.style.display = notesPanel.style.display === "none" ? "block" : "none";
    }
  });
  
  let playlistVideos = [];
  let currentIndex = -1;
  
  function renderPlaylistUI() {
    if(!playlistVideos.length) return;
    
    let html = "";
    playlistVideos.forEach((video, index) => {
      const isCurrent = index === currentIndex;
      const bgStyle = isCurrent ? 
        "background:var(--bs-primary,#1f6feb);color:#fff;" : 
        "background:rgba(255,255,255,0.05);color:var(--gdi-text,#e6edf3);";
      
      html += `<div class="gdi-playlist-item" data-idx="${index}" style="padding:8px 12px;margin:3px 0;border-radius:6px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;font-size:13px;transition:background 0.2s;${bgStyle}">
        <div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:80%;">
          <i class="bi bi-${isCurrent ? "play-fill" : "film"} me-2"></i>
          <span style="font-weight:${isCurrent ? "600" : "400"};">${escHtml(video.name)}</span>
        </div>
        <span style="font-size:11px;opacity:0.8;">${video.size || ""}</span>
      </div>`;
    });
    
    $("#gdi-playlist-list").html(html);
    $("#gdi-playlist-count").text(`${currentIndex + 1} / ${playlistVideos.length}`);
    $("#gdi-playlist-wrap").show();
    
    const navBar = document.getElementById("gdi-player-nav");
    if(navBar && playlistVideos.length > 1) {
      navBar.style.display = "flex";
      document.getElementById("gdi-nav-info").textContent = `${currentIndex + 1} / ${playlistVideos.length}`;
      
      const prevBtn = document.getElementById("gdi-btn-prev");
      const nextBtn = document.getElementById("gdi-btn-next");
      
      prevBtn.disabled = currentIndex <= 0;
      prevBtn.style.opacity = currentIndex <= 0 ? "0.4" : "1";
      nextBtn.disabled = currentIndex >= playlistVideos.length - 1;
      nextBtn.style.opacity = currentIndex >= playlistVideos.length - 1 ? "0.4" : "1";
    }
    
    $(".gdi-playlist-item").off("click").on("click", function() {
      const index = parseInt($(this).data("idx"));
      if(!isNaN(index) && playlistVideos[index]) {
        switchVideo(index);
      }
    });
  }
  
  document.getElementById("gdi-btn-prev")?.addEventListener("click", () => {
    if(currentIndex > 0) {
      switchVideo(currentIndex - 1);
    }
  });
  
  document.getElementById("gdi-btn-next")?.addEventListener("click", () => {
    if(currentIndex < playlistVideos.length - 1) {
      switchVideo(currentIndex + 1);
    }
  });
  
  function switchVideo(index) {
    if(index < 0 || index >= playlistVideos.length) return;
    
    currentIndex = index;
    const video = playlistVideos[currentIndex];
    
    if(video.pageUrl) {
      history.pushState(null, video.name, video.pageUrl);
    }
    
    $(".gdi-file-header-name").text(video.name);
    $(".gdi-file-header-meta").text(video.size);
    
    if(!UI.disable_video_download) {
      $(".gdi-viewer-footer").html(renderDownloadButtons(video.streamUrl, encodeURIComponent(video.name), { showMedia: true }));
    }
    
    if(window._gdiPlayerInstance) {
      if(playerConfig.player === "plyr") {
        window._gdiPlayerInstance.source = {
          type: "video",
          sources: [{ src: video.streamUrl, type: video.streamUrl.includes(".m3u8") ? "application/x-mpegURL" : "video/mp4" }]
        };
        window._gdiPlayerInstance.play().catch(() => {});
      } else if(playerConfig.player === "videojs") {
        window._gdiPlayerInstance.src({ 
          src: video.streamUrl, 
          type: video.streamUrl.includes(".m3u8") ? "application/x-mpegURL" : "video/mp4" 
        });
        window._gdiPlayerInstance.play().catch(() => {});
      }
    }
    
    renderPlaylistUI();
  }
  
  function playNextInPlaylist() {
    if(currentIndex < playlistVideos.length - 1) {
      switchVideo(currentIndex + 1);
    }
  }
  
  const currentPath = window.location.pathname;
  const folderPath = currentPath.split("/").slice(0, -1).join("/") + "/";
  
  function buildPlaylistFromFiles(files, basePath) {
    const videos = [];
    
    files.forEach(file => {
      if(FILE_TYPES.video.includes(file.fileExtension) || (file.mimeType && file.mimeType.includes("video"))) {
        const encodedFileName = encodeURIComponent(file.name);
        const fileStreamUrl = UI.second_domain_for_dl ? UI.downloaddomain + file.link : window.location.origin + file.link;
        const filePageUrl = basePath + encodedFileName + "?a=view";
        
        videos.push({
          name: file.name,
          streamUrl: fileStreamUrl,
          size: formatFileSize(file.size),
          pageUrl: filePageUrl
        });
      }
    });
    
    return videos;
  }
  
  requestListPath(folderPath, {}, function(data) {
    if(!data?.data?.files) return;
    
    const files = data.data.files;
    let videos = buildPlaylistFromFiles(files, folderPath);
    
    playlistVideos = videos;
    currentIndex = playlistVideos.findIndex(v => v.streamUrl === streamUrl);
    
    if(currentIndex === -1 && playlistVideos.length > 0) {
      playlistVideos.unshift({ name, size, streamUrl, pageUrl: window.location.href });
      currentIndex = 0;
    }
    
    renderPlaylistUI();
  }, 2);
}

