function file_audio(name, encodedName, size, streamUrl, fileId, rootId) {
  const UI = window.UI || {};
  const audioList = [{ name: name, url: streamUrl, cover: UI.audioposter }];
  const playerBody = UI.disable_player ? "" : ' <div id="aplayer-container" style="max-width:680px;margin:0 auto;"></div>';
  const footer = !UI.disable_audio_download ? renderDownloadButtons(streamUrl, encodedName, { showMedia: true }) : "";
  
  $("#content").html(_viewerCard('<i class="bi bi-music-note-beamed gdi-icon-audio"></i>', name, size, playerBody, footer));
  
  const styleLink = document.createElement("link");
  styleLink.rel = "stylesheet";
  styleLink.href = "https://cdn.jsdelivr.net/npm/aplayer@1.10.1/dist/APlayer.min.css";
  document.head.appendChild(styleLink);
  
  const scriptEl = document.createElement("script");
  scriptEl.src = "https://cdn.jsdelivr.net/npm/aplayer@1.10.1/dist/APlayer.min.js";
  scriptEl.onload = function() {
    if(!document.getElementById("aplayer-container")) return;
    
    window._gdiAPlayer = new APlayer({
      container: document.getElementById("aplayer-container"),
      mini: false,
      autoplay: false,
      theme: "#4d9fec",
      loop: "all",
      preload: "auto",
      volume: 0.7,
      audio: audioList
    });
  };
  document.head.appendChild(scriptEl);
}

