function file_image(name, encodedName, size, imageUrl) {
  const body = `<div class="gdi-img-wrap"><img src="${imageUrl}" alt="${escHtml(name)}" loading="lazy" style="max-width:100%;height:auto;"></div>`;
  const footer = renderDownloadButtons(imageUrl, encodedName);
  
  $("#content").html(_viewerCard('<i class="bi bi-image gdi-icon-image"></i>', name, size, body, footer));
}

function file_pdf(name, encodedName, size, pdfUrl, fileId, rootId) {
  const body = `
    <div class="gdi-pdf-controls">
      <button id="pdf-prev" class="gdi-btn gdi-btn-ghost gdi-btn-icon"><i class="bi bi-chevron-left"></i></button>
      <span style="font-size:13px;">Page <span id="pdf-page-num">1</span> / <span id="pdf-page-count">?</span></span>
      <button id="pdf-next" class="gdi-btn gdi-btn-ghost gdi-btn-icon"><i class="bi bi-chevron-right"></i></button>
      <input id="pdf-zoom" type="range" min="50" max="200" value="100" style="width:100px;">
      <span id="pdf-zoom-val">100%</span>
    </div>
    <div id="pdf-spinner" class="gdi-spinner-wrap"><div class="gdi-spinner"></div></div>
    <canvas id="pdf-canvas" style="max-width:100%;display:block;margin:auto;"></canvas>`;
  
  const footer = renderDownloadButtons(pdfUrl, encodedName);
  
  $("#content").html(_viewerCard('<i class="bi bi-file-earmark-pdf-fill gdi-icon-pdf"></i>', name, size, body, footer));
  
  let pdfDoc = null;
  let currentPage = 1;
  let scale = 1;
  
  function renderPage() {
    const canvas = document.getElementById("pdf-canvas");
    const ctx = canvas.getContext("2d");
    
    pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js";
    
    function renderPageNumber(pageNum) {
      pdfDoc.getPage(pageNum).then(function(page) {
        const viewport = page.getViewport({ scale: scale });
        canvas.height = viewport.height;
        canvas.width = viewport.width;
        
        page.render({ canvasContext: ctx, viewport: viewport }).promise.then(function() {
          $("#pdf-spinner").hide();
        });
        
        document.getElementById("pdf-page-num").textContent = pageNum;
      });
    }
    
    pdfjsLib.getDocument(pdfUrl).promise.then(function(doc) {
      pdfDoc = doc;
      document.getElementById("pdf-page-count").textContent = doc.numPages;
      renderPageNumber(currentPage);
    }).catch(function(error) {
      $("#pdf-spinner").html(`<div class="gdi-alert gdi-alert-error">Could not load PDF: ${error.message}</div>`);
    });
    
    document.getElementById("pdf-prev").addEventListener("click", function() {
      if(currentPage > 1) {
        currentPage--;
        renderPageNumber(currentPage);
      }
    });
    
    document.getElementById("pdf-next").addEventListener("click", function() {
      if(pdfDoc && currentPage < pdfDoc.numPages) {
        currentPage++;
        renderPageNumber(currentPage);
      }
    });
    
    document.getElementById("pdf-zoom").addEventListener("input", function() {
      scale = parseInt(this.value) / 100;
      document.getElementById("pdf-zoom-val").textContent = this.value + "%";
      renderPageNumber(currentPage);
    });
  }
  
  if(typeof pdfjsLib !== "undefined") {
    renderPage();
  } else {
    const scriptEl = document.createElement("script");
    scriptEl.src = "https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js";
    scriptEl.onload = renderPage;
    document.head.appendChild(scriptEl);
  }
}

function file_code(name, encodedName, size, rawSize, fileUrl, fileExt, fileId, rootId) {
  const UI = window.UI || {};
  
  let body = '<div id="code-spinner"><div class="gdi-spinner-wrap"><div class="gdi-spinner"></div></div></div>';
  body += '<div class="gdi-code-outer" style="display:none;"><pre><code id="editor"></code></pre></div>';
  
  const footer = renderDownloadButtons(fileUrl, encodedName);
  
  $("#content").html(_viewerCard(getFileIcon(fileExt), name, size, body, footer));
  
  if(UI.second_domain_for_dl) return;
  
  if(rawSize <= 1024 * 1024 * 2) {
    $.get(fileUrl, function(content) {
      $("#editor").html($("<div/>").text(content).html());
      $("#code-spinner").remove();
      $(".gdi-code-outer").show();
    });
  } else {
    $("#code-spinner").remove();
    $(".gdi-code-outer").show();
    $("#editor").html('<span style="color:var(--gdi-text-muted);">File too large (max 2 MB)</span>');
  }
}

function file_workspace(name, size, mimeType, downloadUrl) {
  const gdocType = GDOC_TYPES[mimeType];
  if(!gdocType) return;
  
  const exportLinks = gdocType.formats.map(format => 
    `<a class="btn btn-sm btn-outline-secondary me-2 mb-2" href="${downloadUrl}&fmt=${format.ext}" download="${escHtml(name)}.${format.ext}">
      <i class="bi bi-download me-1"></i>${format.label}
    </a>`
  ).join("");
  
  const body = `<p style="color:var(--gdi-text-muted);margin-bottom:12px;">This is a ${gdocType.name}. Choose a format to export.</p><div>${exportLinks}</div>`;
  
  $("#content").html(_viewerCard(gdocType.icon, name, size, body));
}

function file_others(name, encodedName, size, fileUrl) {
  const fileExt = name.split(".").pop();
  const fileIcon = getFileIcon(fileExt);
  const body = '<p style="color:var(--gdi-text-muted);font-size:13px;">No preview available for this file type.</p>';
  const footer = renderDownloadButtons(fileUrl, encodedName);
  
  $("#content").html(_viewerCard(fileIcon, name, size, body, footer));
}

// ════════════════════════════════════════════════════════════════════
// SEARCH
// ════════════════════════════════════════════════════════════════════

function render_search_result_list() {
  const searchQuery = window.MODEL?.q || "";
  
  const html = `
    <div class="gdi-wrap">
      <div id="update"></div>
      <div class="gdi-search-header">Results for <span class="gdi-search-query">"${escHtml(searchQuery)}"</span></div>
      <div id="list"></div>
      <div id="count" class="gdi-count-bar"></div>
    </div>`;
  
  $("#content").html(html);
  $("#list").html('<div class="gdi-spinner-wrap"><div class="gdi-spinner"></div></div>');
  
  function handleSearchResults(data) {
    $("#list").data("nextPageToken", data.nextPageToken);
    $("#spinner").remove();
    
    if(data.nextPageToken === null) {
      $(window).off("scroll");
      window.scroll_status.event_bound = false;
    }
    
    let html = "";
    let fileCount = 0;
    
    if(data.data?.files) {
      data.data.files.forEach(file => {
        if(file.mimeType === "application/vnd.google-apps.folder") {
          html += `<a href="/fallback?id=${escHtml(encodeURIComponent(file.id))}" class="gdi-row">
            <span class="gdi-row-icon"><i class="bi bi-folder-fill"></i></span>
            <span class="gdi-row-name">${escHtml(file.name)}</span>
          </a>`;
        } else {
          fileCount++;
          const fileSize = formatFileSize(file.size);
          const downloadUrl = window.UI?.second_domain_for_dl ? window.UI.downloaddomain + file.link : window.location.origin + file.link;
          
          html += `<div class="gdi-row">
            <span class="gdi-row-icon">${getFileIcon(file.fileExtension)}</span>
            <a class="gdi-row-name" href="${downloadUrl}?a=view">${escHtml(file.name)}</a>
            <span class="gdi-row-size">${fileSize}</span>
            <span class="gdi-row-acts">
              <a class="gdi-act-btn" href="${downloadUrl}" title="Download"><i class="bi bi-download"></i></a>
            </span>
          </div>`;
        }
      });
    }
    
    $("#list").html(html);
    
    const totalResults = data.data?.files?.length || 0;
    $("#count").addClass("show").html(`${totalResults} result${totalResults === 1 ? "" : "s"}`);
  }
  
  requestSearch({ q: searchQuery }, handleSearchResults);
}

