window.addEventListener("beforeunload", () => {
  if(window.GDI_ABORT) {
    window.GDI_ABORT.forEach(controller => {
      try { controller.abort(); } catch(e) {}
    });
    window.GDI_ABORT.clear();
  }
});

window.onpopstate = function() {
  if(window.GDI_ABORT) {
    window.GDI_ABORT.forEach(controller => {
      try { controller.abort(); } catch(e) {}
    });
    window.GDI_ABORT.clear();
  }
  render(window.location.pathname);
};

document.addEventListener("change", function(event) {
  if(event.target && event.target.id === "select-all-checkboxes") {
    document.querySelectorAll("input.gdi-row-check").forEach(checkbox => {
      checkbox.checked = event.target.checked;
    });
  }
});

$(function() {
  console.log("[GDI] Boot sequence started");
  
  GDIUserSystem.loadUserData();
  init();
  
  if(window.UI?.debug_mode && typeof GDIDebug !== "undefined") {
    GDIDebug.attach();
  }
  
  if(window.UI?.show_quota) {
    fetchQuota();
  }
  
  const embedParam = new URLSearchParams(window.location.search).get("embed");
  if(embedParam === "1") {
    document.body.classList.add("embed-mode");
  }
  
  console.log("[GDI] Rendering path:", window.location.pathname);
  render(window.location.pathname);
  
  setTimeout(() => {
    if(window.location.pathname === "/" || window.location.pathname.match(/\/\d+:\/?$/)) {
      showContinueWatchingBanner();
    }
  }, 1000);
  
  console.log("[GDI] Boot complete ✓");
});

function fetchQuota() {
  const driveIndex = window.current_drive_order || 0;
  
  fetch(`/${driveIndex}:quota`)
    .then(response => response.json())
    .then(data => {
      const quota = data.storageQuota;
      if(!quota) return;
      
      const usage = Number(quota.usage || 0);
      const limit = Number(quota.limit || 0);
      const percentage = limit > 0 ? Math.min(100, usage / limit * 100) : 0;
      const color = percentage > 90 ? "#f44336" : percentage > 70 ? "#ff9800" : "#4caf50";
      
      const quotaBar = document.getElementById("gdi-quota-bar");
      const quotaText = document.getElementById("gdi-quota-text");
      const quotaFill = document.getElementById("gdi-quota-fill");
      
      if(quotaBar && quotaText && quotaFill) {
        quotaText.textContent = limit > 0 ? 
          `${formatFileSize(usage)} of ${formatFileSize(limit)} (${percentage.toFixed(1)}%)` : 
          formatFileSize(usage);
        
        quotaFill.style.width = percentage + "%";
        quotaFill.style.background = color;
        quotaBar.style.display = "block";
      }
    })
    .catch(() => {});
}

